UPDATE public.ai_user_prompts
SET
  title = 'Анализ баланса компании',
  description = 'Загрузите бухгалтерский баланс для финансового анализа. AI проанализирует ключевые показатели, коэффициенты и выявит риски.',
  prompt_text = E'Ты получил бухгалтерский баланс компании. Проанализируй его по следующей структуре:\n\n1. **Краткий отчёт извлечения данных**\n   - Какие данные обнаружены в документе (перечисли конкретные показатели и их значения)\n   - Какой период / дата баланса\n   - Формат документа\n\n2. **Чего не хватает для полного анализа**\n   - Какие ключевые показатели отсутствуют\n   - Какие дополнительные документы были бы полезны\n\n3. **Финансовый анализ по имеющимся данным**\n   - Структура активов и пассивов (только по реально найденным данным)\n   - Коэффициенты ликвидности (если данные позволяют)\n   - Коэффициенты финансовой устойчивости (если данные позволяют)\n   - Рентабельность (если есть данные о прибыли)\n   - Для каждого показателя без данных укажи: «Не рассчитывается: данные отсутствуют»\n\n4. **Выявленные риски и проблемы**\n   - На основе ТОЛЬКО реально извлечённых показателей\n\n5. **Ограничения анализа**\n   - Что невозможно оценить из-за неполноты данных\n   - Оговорка о предварительном характере анализа\n\n6. **Рекомендации**\n   - Что загрузить для более точного анализа\n   - Конкретные шаги по улучшению показателей (если данные позволяют)\n\nКРИТИЧЕСКИ ВАЖНО:\n- Если в загруженном файле нет явных числовых данных баланса (активы, пассивы, капитал, выручка), НЕ выполняй расчёт коэффициентов.\n- Ответь: «Данные для анализа не обнаружены в загруженном документе.»\n- Анализируй ТОЛЬКО реально извлечённые значения.\n- НЕ подставляй примерные, типовые или ориентировочные цифры.',
  type = 'file_analysis',
  input_hint = 'Загрузите файл бухгалтерского баланса (Excel, PDF или фото)',
  launcher_title = 'Анализ баланса',
  launcher_description = 'Загрузите баланс компании для финансового анализа с расчётом ключевых показателей'
WHERE code = 'balance_analysis';